        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        dimension = data['dimension']
        distance = data['distance']
        cnt_particles = data['particles']

        if not cnt_particles:
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=[0]*dimension, type='custom')]
            )

        def is_valid(candidate):
            for p in cnt_particles:
                hamming = sum(c != p[i] for i, c in enumerate(candidate))
                if hamming < distance:
                    return False
            return True

        candidate = [0]*dimension
        if is_valid(candidate):
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=candidate, type='custom')]
            )

        candidate = [1]*dimension
        if is_valid(candidate):
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=candidate, type='custom')]
            )

        for p in cnt_particles:
            complement = [1 - bit for bit in p]
            if is_valid(complement):
                return Info(
                    sender=self.__class__.__name__,
                    receiver=message.sender,
                    difficulty=message.difficulty,
                    message=[BaseMessageDataType(data=complement, type='custom')]
                )

        for p in cnt_particles:
            indices = list(range(dimension))
            for bits_to_flip in combinations(indices, distance):
                candidate = p.copy()
                for i in bits_to_flip:
                    candidate[i] = 1 - candidate[i]
                if is_valid(candidate):
                    return Info(
                        sender=self.__class__.__name__,
                        receiver=message.sender,
                        difficulty=message.difficulty,
                        message=[BaseMessageDataType(data=candidate, type='custom')]
                    )

        total = 1 << dimension
        for num in range(total):
            candidate = [(num >> (dimension - 1 - i)) & 1 for i in range(dimension)]
            if is_valid(candidate):
                return Info(
                    sender=self.__class__.__name__,
                    receiver=message.sender,
                    difficulty=message.difficulty,
                    message=[BaseMessageDataType(data=candidate, type='custom')]
                )

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=None, type='custom')]
        )

