        dimension = data['dimension']
        distance = data['distance']
        cnt_particles = data['particles']

        def is_valid(candidate):
            for p in cnt_particles:
                if sum(a != b for a, b in zip(candidate, p)) < distance:
                    return False
            return True

        next_particle = None

        # Step 1: Check all-zeros
        candidate = [0] * dimension
        if is_valid(candidate):
            next_particle = candidate
        else:
            # Step 2: Check all-ones
