                    majority = []
                    for i in range(dimension):
                        count_ones = sum(p[i] for p in cnt_particles)
                        majority_bit = 1 if count_ones > len(cnt_particles) / 2 else 0
                        majority.append(majority_bit)
                    candidate = [1 - bit for bit in majority]
                    if is_valid(candidate):
                        next_particle = candidate

                # Step 4: Check particle complements
                if next_particle is None:
                    for p in cnt_particles:
                        candidate = [1 - x for x in p]
                        if is_valid(candidate):
                            next_particle = candidate
                            break

                # Step 5: Random search
                if next_particle is None:
                    for _ in range(1000):
                        candidate = [random.choice([0, 1]) for _ in range(dimension)]
                        if is_valid(candidate):
                            next_particle = candidate
                            break

                # Step 6: Exhaustive search for small dimensions
                if next_particle is None and dimension <= 20:
                    for bits in product([0, 1], repeat=dimension):
                        candidate = list(bits)
                        if is_valid(candidate):
                            next_particle = candidate
                            break

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_particle, type='custom')]
        )

