    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def generate_minority_candidate(self, particles, dimension):
        if not particles:
            return [0] * dimension
        candidate = []
        for i in range(dimension):
            count0 = sum(1 for p in particles if p[i] == 0)
            count1 = len(particles) - count0
            if count0 <= count1:
                candidate.append(1)
            else:
                candidate.append(0)
        return candidate

    def is_valid(self, candidate, particles, distance):
        for p in particles:
            hd = sum(c != p[i] for i, c in enumerate(candidate))
            if hd < distance:
                return False
        return True

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        dimension = data['dimension']
        distance = data['distance']
        particles = data['particles']

        next_particle = None

        if not particles:
            next_particle = [0] * dimension
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=next_particle, type='custom')]
            )

        first_particle = particles[0]
        complement = [1 - b for b in first_particle]
        if self.is_valid(complement, particles, distance):
            next_particle = complement
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=next_particle, type='custom')]
            )

        minority_candidate = self.generate_minority_candidate(particles, dimension)
        if self.is_valid(minority_candidate, particles, distance):
            next_particle = minority_candidate
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=next_particle, type='custom')]
            )

        for p in particles:
            for bits in itertools.combinations(range(dimension), distance):
                candidate = list(p)
                for i in bits:
                    candidate[i] = 1 - candidate[i]
                if self.is_valid(candidate, particles, distance):
                    next_particle = candidate
                    return Info(
                        sender=self.__class__.__name__,
                        receiver=message.sender,
                        difficulty=message.difficulty,
                        message=[BaseMessageDataType(data=next_particle, type='custom')]
                    )

        for num in range(2 ** dimension):
            candidate = [(num >> i) & 1 for i in range(dimension)]
            if self.is_valid(candidate, particles, distance):
                next_particle = candidate
                return Info(
                    sender=self.__class__.__name__,
                    receiver=message.sender,
                    difficulty=message.difficulty,
                    message=[BaseMessageDataType(data=next_particle, type='custom')]
                )

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_particle, type='custom')]
        )

